// Túnel ngrok gratuito en wlan0 (10.22.160.24)
// Expone FastAPI :8000 al mundo vía HTTPS/WSS
//
// WSS:   wss://unmoral-shrink-cavalry.ngrok-free.dev/ws/cobot
// HTTPS: https://unmoral-shrink-cavalry.ngrok-free.dev/api/*
//
// Iniciado por start_gateway.sh al arrancar la RPi
return msg;

// backend.py — FastAPI + uvicorn en 0.0.0.0:8000
//
// Endpoints REST:
//   GET  /health
//   GET  /api/cobot/state
//   POST /api/cobot/move/joint   {joints:[°×6], speed:%}
//   POST /api/cobot/stop
//   POST /api/cobot/power_on  /enable
//   POST /api/cobot/gripper/open  /close
//   POST /api/cobot/conveyor/start  /stop
//   POST /api/camera/snapshot
//   POST /api/table/home  /work
//   POST /api/cycle/start  /stop  /status
//
// WS /ws/cobot → snapshot JSON @ 100 ms
return msg;

// Máquina de estados de 32 pasos (cycle_runner.py):
// 0-1:   Init — power_on + enable + turntable home
// 2-11:  Pick del conveyor → Fixture A
//        (espera DI9 photoelectric @200ms polling)
// 12-13: Remachado 30s (turntable limit1 → limit2 → limit1)
// 14-23: Inspección visión (→ cámara, espera 5s, trigger)
// 24-32: Routing PASS→Bin OK / FAIL→Bin KO + return HOME
//
// Salidas:
//   0 → Cobot Modbus/TLS (movimiento, gripper, conveyor)
//   1 → HMI Modbus (LEDs, contadores)
//   2 → Camera HTTP (trigger, captura imagen)
//   3 → Cobot FTP  (upload programas)
//   4 → GPIO (stepper turntable, solenoid)
const state = context.get('cycleState') || 'IDLE';
msg._state = state;
return [msg, msg, msg, msg, msg];

// cycle_pipeline.py — Async task scheduler
// Gestiona múltiples piezas en paralelo en la pipeline:
//   pieza_1: en conveyor   pieza_2: en inspección
//
// Contadores:
//   COUNT.total      → HMI Reg 1
//   COUNT.accepted   → HMI Reg 2
//   COUNT.rejected   → HMI Reg 3
//
// Tabla lineal (table_control.py):
//   GPIO18 STEP  GPIO23 DIR  → stepper NEMA17
//   GPIO24 limit_HOME  GPIO25 limit_WORK
return msg;

// systemd service: cobot-nat.service
// Activa al boot:
//   sysctl net.ipv4.ip_forward=1
//   iptables -t nat -A POSTROUTING -o eth0 -j MASQUERADE
//   iptables -A FORWARD -i eth1 -o eth0 -j ACCEPT
//   iptables -A FORWARD -i eth0 -o eth1 -m state --state RELATED,ESTABLISHED -j ACCEPT
//
// Permite que 192.168.1.x llegue a 10.5.5.100 (cobot)
// y que la RPi enrute comandos entre ambas redes
return msg;

